def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    try:
        with open(urls_file, 'r') as file:
            for url in file:
                url = url.strip()  # Remove any leading/trailing whitespace
                if url:
                    collect_from_url(url, archive_dir=archive_dir, notes=notes)
    except FileNotFoundError:
        print(f"Error: The file {urls_file} was not found.")
    except IOError as e:
        print(f"Error reading the file {urls_file}: {e}")
